import{z as s,x as n,o as B,c as T,q as o,j as t,D as E,d as l,s as i,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"SLO 与尾延迟","description":"","frontmatter":{"title":"SLO 与尾延迟","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/serving-slo.md","filePath":"llm/serving-slo.md","lastUpdated":1791413859000}'),p={name:"llm/serving-slo.md"};function d(m,a,h,P,S,L){const r=n("Mermaid");return B(),T("div",null,[a[2]||(a[2]=o('<h1 id="slo-与尾延迟" tabindex="-1">SLO 与尾延迟 <a class="header-anchor" href="#slo-与尾延迟" aria-label="Permalink to &quot;SLO 与尾延迟&quot;">​</a></h1><div class="epigraph"><p>平均数达标只说明大部分请求还行；用户投诉和合同违约发生在分布的尾巴上——那一截由长提示、队头阻塞、偶发抢占和一次过长的前填共同写成。</p><footer>—— 把服务等级目标写成 TTFT / TBT 分位数，而不是写成平均延迟</footer></div><p><a href="/llm/memory-breakdown">上一课</a>把服务显存拆成权重地板与随 \\(L,n,h_{\\mathrm{kv}}\\) 涨的 KV；能 decode 的长度未必能一次 prefill。缺口是合同：分解告诉你炸在哪一类对象，不规定延迟分位数写给谁、尾巴从排队还是从某次迭代来。本课钉 SLO 与尾延迟：TTFT 与 ITL 分列，均值不能签字。不重讲 KV 公式。有效容量见 <a href="/llm/goodput">goodput</a>；过载先保谁见 <a href="/llm/priority-sla">优先级</a>。后课污染评测默认服务合同已经按尾部而不是空载均值来写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>显存分解告诉你炸在哪一类对象；合同还要规定延迟分位数写给谁。延迟在生成服务上不是单峰对称的。短提示空载时 TTFT 可以是几十毫秒；同一系统里，一条 32k 文档、或排在超长前填后面的聊天，TTFT 可以是数秒。平均被大量短请求拉低，P99 被少数长作业与排队决定。交互产品的失败体验几乎总是尾巴：一次卡死的打字机、一次始终不出字的对话框。把均值写进 SLO，调度器会继续优化好服务的那一部分，违约集中在投诉用户上。</p><p>生成还把尾巴拆成两种形状。TTFT 的尾巴偏排队与前填长度，一次违约是「半天没开始」。ITL 的尾巴偏某一次迭代被长作业或通信打穿，用户感觉是说话突然停住。两种尾巴的治理不同，不能收成一个 E2E P99 了事——E2E 还把输出长度混进来：爱写长的模型天然 E2E 更大，那不是服务变慢。</p><p><span class="marginnote">数字实例：1000 个请求里 P99 是 2 秒，意思是允许最慢的 10 个超过 2 秒，其余 990 个必须更快；均值哪怕只有 200 毫秒也与它不矛盾——平均值被 990 个快请求拉低，而投诉恰好集中在那 10 个上。这就是均值不能写进 SLO 的算术原因。</span></p><h3 id="slo-要有范围-否则不可执行" tabindex="-1">SLO 要有范围，否则不可执行 <a class="header-anchor" href="#slo-要有范围-否则不可执行" aria-label="Permalink to &quot;SLO 要有范围，否则不可执行&quot;">​</a></h3><p>一条可调度的 SLO 至少声明：请求类别、模型与精度、提示与输出长度桶（或上限）、测点（网关收到完整提示到第一个可见 token / 逐步 token）、分位数与窗口（例如 5 分钟滚动 P99）、达成率（例如 99% 的时间窗口达标）。缺任何一项，数字都可以用换模型、换长度、换测点来「达成」。范围也是拒绝的依据：超长提示不在合同内，应改类或拒绝，而不是让它们去打所有人的尾巴。</p><p><span class="marginnote">SLO 不是压测峰值。把实验室里刚饱和前的 P99 写成合同，上线后流量相关、缓存失效、换出风暴都会集体违约。对内阈值应严于对外 SLA，中间留给抢占、重试和故障。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>尾延迟用顺序统计量。窗口内对该类请求的 \\(\\mathrm{TTFT}\\) 样本取经验分位数 \\(q_{0.99}\\)。样本少则估计噪声大：P99 大约是百分之一的点，几百个样本远远不够。SLO 监控需要足够的完成量，或改用 P95 加更长窗口。对 ITL，有两种写法：按请求平均 TPOT 的 P99（弱，会吃掉逐步尖刺），或按逐步 TBT 违约率（强：任一步超过 \\(t\\) 即记该请求违约）。交互产品更接近后者；Sarathi 一类工作把 TBT 当作一等目标，正是这个原因。</p><p><span class="marginnote">常见误区：初学者容易以为压测跑 500 条请求就能报 P99，实际上 P99 关心的是最慢的 1%，500 条里只有约 5 个样本落在这一档，一两条异常就能让估计值大幅摆动。想要稳定的 P99，要么累计上万样本，要么退而求其次签 P95 加长窗口。</span></p><p>控制环把分位数接回调度。观测到交互类 TTFT 的滚动 P95 逼近阈值，就减低优先级准入、限制同时前填条数、或缩小 decode 批。等到均值报警往往太晚。老化（已等待时长 / 截止时间）让接近违约的请求获得临时提升，专门打尾巴，而不是打平均。</p> \\[\\mathrm{breach}=\\mathbf{1}\\bigl[q_{p}(\\mathrm{TTFT})\\gt T_1\\ \\lor\\ \\mathrm{TBT\\text{-}viol}\\gt \\rho\\bigr] \\]<p>窗口级 <code>breach</code> 用于告警与自动降级（关投机、减 <code>max_tokens</code>、拒绝批处理类）。请求级违约用于 <a href="/llm/goodput">goodput</a> 计数。两级都要，只留告警没有请求级滤镜，容量规划仍会按吞吐来。</p><h3 id="尾巴的常见生成器" tabindex="-1">尾巴的常见生成器 <a class="header-anchor" href="#尾巴的常见生成器" aria-label="Permalink to &quot;尾巴的常见生成器&quot;">​</a></h3><p>原子长前填：一次 \\(O(n^2)\\) 作业把同卡所有 ITL 拉到前填时长，并让队列里所有 TTFT 加上这段。队头阻塞：FCFS 下超长作业之后的短请求继承等待。KV 满导致的换出/重算：受害者恢复时出现 TTFT 式尖刺。批过大：每步墙钟基线抬高，P50 和 P99 一起坏，这是工作点错了，不是偶发尾。冷启动、核编译、专家缺页：稀疏模型上会制造与负载无关的尖刺，应从稳态 SLO 中剔除并单独设发布检查。</p>',18)),(B(),t(A,null,{default:E(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20CLS%5B%22%E7%B1%BB%E5%88%AB%E4%B8%8E%E9%95%BF%E5%BA%A6%E6%A1%B6%22%5D%0A%20%20CLS%20--%3E%20SLO%5B%22TTFT%20%E5%88%86%E4%BD%8D%E6%95%B0%20%2B%20TBT%20%E8%BF%9D%E7%BA%A6%E7%8E%87%22%5D%0A%20%20SLO%20--%3E%20OK%7B%22%E7%AA%97%E5%8F%A3%E8%BE%BE%E6%A0%87%3F%22%7D%0A%20%20OK%20--%3E%7C%E5%90%A6%7C%20ACT%5B%22%E9%99%90%E6%B5%81%20%2F%20%E5%87%8F%E6%89%B9%20%2F%20%E6%8B%92%E9%95%BF%E4%BD%9C%E4%B8%9A%22%5D%0A%20%20ACT%20--%3E%20GP%5B%22goodput%20%E5%B7%A5%E4%BD%9C%E7%82%B9%E5%B7%A6%E7%A7%BB%22%5D%0A%20%20TAIL%5B%22%E9%95%BF%E5%89%8D%E5%A1%AB%20%2F%20%E6%8D%A2%E5%87%BA%20%2F%20%E5%A4%A7%E6%89%B9%22%5D%20--%3E%20SLO%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"排队论里，利用率靠近 1 时等待时间的尾部比均值恶化得更快。连续批把 GPU 往高利用率推，正好踩在这一区：吞吐好看，P99 爆炸。分块前填给单次迭代加时间盖，等于把服务时间的方差砍掉一块，尾巴从「碰上 100k 提示」变成「块数 × 块时延」，可预测性上升，均值未必下降。优先级把不同类别放进不同有效利用率：交互类看到的负载被故意压在饱和点以下，批处理类去填剩余——交互 P99 改善，全局吞吐可能略降。",-1)),a[5]||(a[5]=e("p",null,"交互类与批处理类分池后，吞吐去哪了、尾巴去哪了：",-1)),(B(),t(A,null,{default:E(()=>[i(r,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIX%5B%22%E6%B7%B7%E5%90%88%E8%B4%9F%E8%BD%BD%3A%20%E4%BA%A4%E4%BA%92%E7%B1%BB%20%2B%20%E6%89%B9%E5%A4%84%E7%90%86%E7%B1%BB%22%5D%20--%3E%20HI%5B%22%E5%85%A8%E9%83%A8%E6%8A%A2%E5%90%8C%E4%B8%80%E6%B1%A0%3A%20%E5%88%A9%E7%94%A8%E7%8E%87%E8%B4%B4%E8%BF%91%201%22%5D%0A%20%20HI%20--%3E%20BOOM%5B%22P99%20%E5%B0%BE%E9%83%A8%E5%85%88%E4%BA%8E%E5%9D%87%E5%80%BC%E7%88%86%E7%82%B8%22%5D%0A%20%20MIX%20--%3E%20SPL%5B%22%E6%8C%89%E4%BC%98%E5%85%88%E7%BA%A7%E5%88%86%E6%B1%A0%22%5D%0A%20%20SPL%20--%3E%20INT%5B%22%E4%BA%A4%E4%BA%92%E7%B1%BB%E5%8E%8B%E5%9C%A8%E9%A5%B1%E5%92%8C%E7%82%B9%E4%BB%A5%E4%B8%8B%22%5D%0A%20%20INT%20--%3E%20P99%5B%22%E4%BA%A4%E4%BA%92%20P99%20%E8%BE%BE%E6%A0%87%22%5D%0A%20%20SPL%20--%3E%20BAT%5B%22%E6%89%B9%E5%A4%84%E7%90%86%E7%B1%BB%E5%A1%AB%E5%89%A9%E4%BD%99%E5%AE%B9%E9%87%8F%22%5D%0A%20%20BAT%20--%3E%20THR%5B%22%E5%85%A8%E5%B1%80%E5%90%9E%E5%90%90%E7%95%A5%E9%99%8D%22%5D%0A%20%20P99%20--%3E%20TRD%5B%22%E7%94%A8%E5%B3%B0%E5%80%BC%E5%90%9E%E5%90%90%E6%8D%A2%E5%8F%AF%E9%A2%84%E6%B5%8B%E7%9A%84%E5%B0%BE%E5%B7%B4%22%5D%0A%20%20THR%20--%3E%20TRD%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">直觉类比：把利用率从 0.8 提到 0.95，就像把超市收银台从「平均排 4 个人」压到「几乎随时满员」——每小时服务的人确实变多了，但来客节奏稍有波动，队伍长度不是按比例变长，而是爆炸式变长。尾延迟对利用率的反应正是这种非线性。</span></p><h3 id="相关突发与缓存双峰" tabindex="-1">相关突发与缓存双峰 <a class="header-anchor" href="#相关突发与缓存双峰" aria-label="Permalink to &quot;相关突发与缓存双峰&quot;">​</a></h3><p>尾部对相关性敏感。独立短请求的 P99 已经不好看时，若再叠加「所有人同时发长文档」（会议纪要场景），分位数模型会失效。SLO 压测必须含突发与相关性，而不是只有泊松到达的均值负载。缓存命中制造双峰：命中极快、未命中走二次前填，混合 P99 由未命中峰决定。报表分列后，合同可以写成「未命中桶的 P99」，避免被命中流量粉饰。</p><p><span class="marginnote">P99.9 在中小流量上几乎不可估，会变成「今天最倒霉的那一条」。没有足够样本就不要签三九。用最大延迟当 SLO 更糟：它随观测时间单调变坏，激励停止测量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>守尾部通常要牺牲峰值吞吐：减批、拒长、为交互留空槽。这是显式的经营选择，应通过 goodput 与成本一起看，而不是假装能同时要满载和极紧 P99。多类 SLO 档位不宜过多，否则无法解释某条请求为何违约。数字必须钉模型和模板：换 70B、打开思维链、换 FP8，旧 SLO 作废。</p><p>SLO 管不了模型质量。TTFT 达标但胡言乱语，合同在性能上成立、在产品上失败。性能 SLO 与质量门禁（自动基准、抽检）并行，不要把 Arena 分数写进延迟合同。前端与网关超时若比 SLO 更短，用户先断开，服务端仍可能把请求算完成——测点要与用户可见超时对齐，否则出现「SLO 绿、投诉红」。</p><p>跨区域、抢占式云实例、降级到更慢卡，都应视为合同范围变化。自动降级时要改对外预期或切类别，而不是默默用更差硬件去追同一 P99。</p><p><span class="marginnote">日志里的 P99 受计时精度、时钟回拨、重试重复计数污染。同一请求重试三次，三条都进分位数，会把尾巴写得更肥或更瘦，取决于你怎么去重。合同统计必须按用户可见的一次尝试定义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SLO 是带范围的分位数合同（TTFT、TBT/ITL），不是平均延迟；SLA 对外更松。</li><li>交互尾巴来自长前填、排队、换出和大批；E2E 均值会把输出长度与两类尾巴混在一起。</li><li>窗口级违约驱动降级，请求级违约驱动 goodput；两者都需要足够样本。</li><li>高利用率让尾部先于均值爆炸；分块、优先级、拒绝是在买可预测的尾巴。</li><li>缓存命中、突发相关、冷启动必须分列，避免粉饰或冤枉稳态调度。</li><li>数字钉模型、精度、长度桶和测点；质量与性能分开签。</li><li>出处：对照生成服务中 TBT/TTFT 分位数实践（如 Sarathi-Serve 对逐步时限的强调）以及排队系统中尾延迟随利用率恶化的一般事实；优先级落地见站内 SLA 专文。</li></ul>',11))])}const c=s(p,[["render",d]]);export{D as __pageData,c as default};
